import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0025 (Remaining): HTTP Client/Server v1.x and v2 Enhancements","description":"","frontmatter":{"title":"ADR-0025 (Remaining): HTTP Client/Server v1.x and v2 Enhancements","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"proposed","status_note":"Proposed"},"headers":[],"relativePath":"web/project/adrs/0025-http-server-remaining.md","filePath":"vendored/web/project/adrs/0025-http-server-remaining.md"}`),a={name:`web/project/adrs/0025-http-server-remaining.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0025-remaining-http-client-server-v1-x-and-v2-enhancements" tabindex="-1">ADR-0025 (Remaining): HTTP Client/Server v1.x and v2 Enhancements <a class="header-anchor" href="#adr-0025-remaining-http-client-server-v1-x-and-v2-enhancements" aria-label="Permalink to “ADR-0025 (Remaining): HTTP Client/Server v1.x and v2 Enhancements”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>ADR-0025 v1 (HTTP Client/Server Crate Split and v1 Server Runtime) has been implemented and archived, with v1 features complete: client crates renamed, <code>Module</code>/<code>ModuleHost</code> async/operation dispatch, abstract and concrete server implementations, HTTP/2 and <code>matchit</code> routing all in place.</p><p>The following work remains for v1.x stability and v2 enhancements.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Implement the remaining HTTP server enhancements:</p><h3 id="v1-x-completion" tabindex="-1">v1.x Completion <a class="header-anchor" href="#v1-x-completion" aria-label="Permalink to “v1.x Completion”">​</a></h3><ul><li><strong>handl <code>FunctionValue</code> route handler dispatch.</strong> The abstract <code>route</code> and <code>route_function</code> methods are stubbed with placeholders. Implement full dispatch of handl <code>FunctionValue</code>s as route handlers via the VM, with proper error handling and response serialization.</li></ul><h3 id="v2-features" tabindex="-1">v2 Features <a class="header-anchor" href="#v2-features" aria-label="Permalink to “v2 Features”">​</a></h3><ul><li><strong>TLS termination.</strong> Add TLS/HTTPS support via <code>rustls</code> or native TLS, with certificate loading and SNI support.</li><li><strong>Middleware hooks.</strong> Provide a composable middleware/layer API for request/response interception (similar to <code>tower</code> or <code>actix-web</code> middleware).</li><li><strong>Compression.</strong> Add transparent <code>gzip</code>/<code>brotli</code> response compression with <code>Accept-Encoding</code> negotiation.</li><li><strong>CORS and rate-limiting.</strong> Provide built-in CORS policy handling and per-IP or per-handler rate-limiting.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>v1.x: handl server applications can use real handl functions as route handlers with full type and error information.</li><li>v2: HTTP/2 + TLS + middleware make handl servers production-ready without a reverse proxy.</li><li>v2: Middleware hooks enable pluggable compression, CORS, rate-limiting, observability, and custom request/response handling.</li></ul><h2 id="related-work" tabindex="-1">Related work <a class="header-anchor" href="#related-work" aria-label="Permalink to “Related work”">​</a></h2><ul><li><code>project/adrs/archived/0025-http-server.md</code> — v1 completed features</li><li><code>project/adrs/archived/0025-http-server-v1-complete.md</code> — v1 final status</li><li>Crates: <code>plugin-lib-http-server</code>, <code>plugin-lib-http-server-std</code></li></ul>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};